    CalculationProject Blank() => new() { Start = DateOnly.FromDateTime(DateTime.Today), End = DateOnly.FromDateTime(DateTime.Today), ScheduleEnd = DateOnly.FromDateTime(DateTime.Today), FirstAmount = 0, MonthlyAmount = 0, Organization = settings.Organization, Manager = settings.Manager, Signatories = settings.Signatories.Where(s => s.Id == Signatory.Moroz.Id).ToList(), Document = settings.Document };
    Button Button(string label, Func<Task> action) { var b = new Button { Content = label, Padding = new(14, 9), Margin = new(0, 0, 7, 5), CornerRadius = new(6) }; b.Click += async (_, _) => await Run(action); return b; }
    async Task Run(Func<Task> action) { if (busy) return; busy = true; body.IsEnabled = false; try { await action(); } catch (Exception ex) { status.Text = "Не выполнено: " + ex.Message; await Ask("Проверьте данные", ex.Message, "Понятно"); } finally { busy = false; body.IsEnabled = true; } }
    async Task<string> Ask(string title, string message, params string[] choices)
    {
        var dialog = new Window { Title = title, Width = 560, SizeToContent = SizeToContent.Height, MaxHeight = 650, WindowStartupLocation = WindowStartupLocation.CenterOwner, CanResize = false }; var panel = new StackPanel { Margin = new(24), Spacing = 18 }; panel.Children.Add(new ScrollViewer { MaxHeight = 430, Content = new TextBlock { Text = message, TextWrapping = TextWrapping.Wrap } }); var buttons = new WrapPanel(); foreach (var c in choices) { var b = new Button { Content = c, Margin = new(0, 0, 8, 0) }; b.Click += (_, _) => dialog.Close(c); buttons.Children.Add(b); }
        panel.Children.Add(buttons); dialog.Content = panel; return await dialog.ShowDialog<string>(this) ?? choices.Last();
    }
    async Task<bool> CanLeave() { if (!dirty) return true; var answer = await Ask("Несохранённые изменения", "Сохранить изменения текущего проекта?", "Сохранить", "Не сохранять", "Отмена"); if (answer == "Отмена") return false; if (answer == "Сохранить") { try { await Save(false); } catch (Exception ex) { await Ask("Сохранение", ex.Message, "Понятно"); return false; } return !dirty; } return true; }
    void Changed() { if (loading) return; dirty = true; file = file with { Result = null }; status.Text = "Есть изменения · требуется пересчёт"; }
    TextBox Field(string key, string label, string value, Panel parent, double width = 240, bool multi = false)
    {
        var box = new TextBox { Text = value, Width = width, AcceptsReturn = multi, MinHeight = multi ? 70 : 34, TextWrapping = multi ? TextWrapping.Wrap : TextWrapping.NoWrap }; fields[key] = box; var group = new StackPanel { Spacing = 5, Margin = new(0, 0, 18, 14) }; group.Children.Add(new TextBlock { Text = label, Foreground = Muted, FontSize = 12 }); group.Children.Add(box); parent.Children.Add(group); box.TextChanged += (_, _) => { if (box.IsFocused) Changed(); }; return box;
    }
    static DateOnly Date(string s) => DateOnly.TryParseExact(s.Trim(), ["dd.MM.yyyy", "d.M.yyyy", "yyyy-MM-dd"], CultureInfo.InvariantCulture, DateTimeStyles.None, out var d) ? d : throw new ArgumentException("Введите дату в формате ДД.ММ.ГГГГ.");
    static decimal Amount(string s) => decimal.TryParse(s.Replace(" ", "").Replace("\u00a0", "").Replace(',', '.'), NumberStyles.AllowLeadingSign | NumberStyles.AllowDecimalPoint, CultureInfo.InvariantCulture, out var v) ? v : throw new ArgumentException("Введите число, например 6038,45.");
    static int Day(string text) { var n = Amount(text); if (n != decimal.Truncate(n) || n < 1 || n > 31) throw new ArgumentException("Число месяца — целое число от 1 до 31."); return (int)n; }
    void Commit() { if (fields.Count == 0) return; string T(string k) => fields[k].Text ?? ""; file = file with { Project = file.Project with { Number = T("number"), Debtor = T("debtor"), Organization = T("organization"), Manager = T("manager"), Executor = T("executor"), Basis = T("basis"), CalculationDate = Date(T("date")), Start = Date(T("start")), End = Date(T("end")), ScheduleEnd = Date(T("scheduleEnd")), MonthlyDay = Day(T("day")), JanuaryDay = Day(T("january")), FirstAmount = Amount(T("first")), MonthlyAmount = Amount(T("monthly")), FixedRate = fixedRate?.IsChecked == true, FixedRatePercent = fixedRate?.IsChecked == true ? Amount(T("rate")) : file.Project.FixedRatePercent } }; }
    async Task Calculate() { Commit(); UseAvailableCbrRates(); var snapshot = file.Project; var result = await Task.Run(() => calculator.Calculate(snapshot)); file = file with { Result = result }; status.Text = $"Расчёт выполнен · {result.Intervals.Length} интервалов · {result.Days} дней"; }
    async Task Navigate(string target) { Commit(); if (target is "Результат" or "Документ" && file.Result == null) await Calculate(); page = target; Render(); }
    void Render() { loading = true; fields.Clear(); fixedRate = null; subtitle.Text = $"{(string.IsNullOrWhiteSpace(file.Project.Debtor) ? "Новый проект" : file.Project.Debtor)}  /  № {file.Project.Number}  /  {page}"; body.Content = page switch { "Ключевая ставка ЦБ" => RatesView(), "История ставок ЦБ РФ" => CbrHistoryView(), "События" => EventsView(), "Результат" => ResultView(), "Документ" => DocumentView(), "История" => HistoryView(), _ => GeneralView() }; loading = false; }
