    static Control Scroll(Control c) => new ScrollViewer { Content = c, HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled };
    static Control TitleBlock(string title, string caption) => new StackPanel { Spacing = 5, Margin = new(0, 0, 0, 15), Children = { new TextBlock { Text = title, FontSize = 20, FontWeight = FontWeight.SemiBold, Foreground = Navy }, new TextBlock { Text = caption, Foreground = Muted, TextWrapping = TextWrapping.Wrap } } };
    static DataGrid GridFor<T>(IEnumerable<T> items, params (string Header, string Path, double Width)[] columns) { var grid = new DataGrid { ItemsSource = items, AutoGenerateColumns = false, IsReadOnly = true, GridLinesVisibility = DataGridGridLinesVisibility.Horizontal, SelectionMode = DataGridSelectionMode.Single, MinHeight = 190, Background = Brushes.White, RowHeight = 36 }; foreach (var c in columns) grid.Columns.Add(new DataGridTextColumn { Header = c.Header, Binding = new Binding(c.Path), Width = new DataGridLength(c.Width, DataGridLengthUnitType.Star) }); return grid; }
    Control EventsView()
    {
        var grid = GridFor(file.Project.Events.OrderBy(e => e.Date).ThenBy(e => e.Kind).ToArray(), ("Дата", "DateText", 1), ("Событие", "KindText", 1.2), ("Сумма / ставка", "ValueText", 1.2), ("Комментарий", "Comment", 2), ("Источник", "OriginText", 1)); var layout = new Grid { RowDefinitions = new("Auto,Auto,*,Auto") }; layout.Children.Add(TitleBlock("События расчёта", "Начисления, оплаты и ставки в одном списке. Выберите строку для изменения."));
        var filterRow = new WrapPanel(); var filter = new ComboBox { ItemsSource = new[] { "Все события", "Начисления", "Оплаты", "Ставки" }, SelectedIndex = 0, Width = 170, Margin = new(0, 0, 12, 12) };
