        void Filter() { var q = filterText.Text ?? ""; grid.ItemsSource = file.Project.Events.Where(e => (filter.SelectedIndex == 0 || e.Kind == (filter.SelectedIndex == 1 ? EventKind.Accrual : filter.SelectedIndex == 2 ? EventKind.Payment : EventKind.Rate)) && ($"{e.DateText} {e.ValueText} {e.Comment}".Contains(q, StringComparison.OrdinalIgnoreCase))).OrderBy(e => e.Date).ThenBy(e => e.Kind).ToArray(); }
        filter.SelectionChanged += (_, _) => Filter(); filterText.TextChanged += (_, _) => Filter(); Grid.SetRow(grid, 2); layout.Children.Add(grid);
        var edit = new StackPanel { Spacing = 8, Margin = new(0, 15, 0, 0) }; var row = new WrapPanel(); var dateBox = new TextBox { Text = $"{file.Project.Start:dd.MM.yyyy}", Width = 150, Margin = new(0, 0, 10, 0) }; var kind = new ComboBox { ItemsSource = new[] { "Начисление", "Оплата", "Ставка" }, SelectedIndex = 0, Width = 160, Margin = new(0, 0, 10, 0) }; var value = new TextBox { PlaceholderText = "Сумма / %", Width = 150, Margin = new(0, 0, 10, 0) }; var comment = new TextBox { PlaceholderText = "Комментарий", Width = 250 }; foreach (var c in new Control[] { dateBox, kind, value, comment }) row.Children.Add(c); edit.Children.Add(row);
        Guid? selected = null; grid.SelectionChanged += (_, _) => { if (grid.SelectedItem is CalculationEvent e) { selected = e.Id; dateBox.Text = e.DateText; kind.SelectedIndex = e.Kind == EventKind.Accrual ? 0 : e.Kind == EventKind.Payment ? 1 : 2; value.Text = e.ValueText; comment.Text = e.Comment; } };
        Task Put(bool update) { var k = kind.SelectedIndex == 0 ? EventKind.Accrual : kind.SelectedIndex == 1 ? EventKind.Payment : EventKind.Rate; if (update && selected == null) throw new ArgumentException("Выберите событие в таблице."); var e = new CalculationEvent(update ? selected!.Value : Guid.NewGuid(), Date(dateBox.Text ?? ""), k, Amount(value.Text ?? ""), comment.Text ?? ""); var list = file.Project.Events.Where(x => !update || x.Id != e.Id).Append(e).ToList(); var p = file.Project with { Events = list }; Calculator.Validate(p); file = file with { Project = p, Result = null }; dirty = true; Render(); return Task.CompletedTask; }
        var actions = new WrapPanel(); actions.Children.Add(Button("Добавить", () => Put(false))); actions.Children.Add(Button("Сохранить изменение", () => Put(true))); actions.Children.Add(Button("Удалить", async () => { if (selected == null) return; if (await Ask("Удаление события", "Удалить выбранное событие?", "Удалить", "Отмена") != "Удалить") return; file = file with { Project = file.Project with { Events = file.Project.Events.Where(e => e.Id != selected).ToList() }, Result = null }; dirty = true; Render(); })); actions.Children.Add(Button("Рассчитать", () => Navigate("Результат"))); edit.Children.Add(actions); Grid.SetRow(edit, 3); layout.Children.Add(edit); return layout;
