    async Task NewProject() { if (!await CanLeave()) return; file = new() { Project = Blank() }; path = null; dirty = false; page = "Общие сведения"; Render(); }
    async Task LoadExample() { if (!await CanLeave()) return; fields.Clear(); file = new() { Project = ReferenceExample.Create() }; path = null; dirty = true; page = "Результат"; await Calculate(); Render(); }
    async Task Open() { if (!await CanLeave()) return; var picks = await StorageProvider.OpenFilePickerAsync(new() { Title = "Открыть проект", AllowMultiple = false, FileTypeFilter = [new("Проект LexPercent") { Patterns = ["*.lpp", "*.bak"] }] }); if (picks.Count > 0) await OpenPath(picks[0].TryGetLocalPath()!); }
    async Task OpenPath(string selected) { var loaded = await store.LoadAsync(selected); Calculator.Validate(loaded.Project); loaded = loaded with { Result = await Task.Run(() => calculator.Calculate(loaded.Project)) }; file = loaded; path = selected; dirty = false; page = "Результат"; Render(); Remember(selected); }
    async Task Save(bool asNew) { Commit(); if (file.Result == null) await Calculate(); var target = path; if (asNew || target == null) { var pick = await StorageProvider.SaveFilePickerAsync(new() { Title = "Сохранить проект", SuggestedStartLocation = Directory.Exists(settings.ProjectDirectory) ? await StorageProvider.TryGetFolderFromPathAsync(settings.ProjectDirectory) : null, SuggestedFileName = $"{file.Project.Number} — {file.Project.Debtor}.lpp", DefaultExtension = "lpp", FileTypeChoices = [new("Проект LexPercent") { Patterns = ["*.lpp"] }] }); target = pick?.TryGetLocalPath(); if (target == null) return; } file = await store.SaveAsync(target, file); path = target; dirty = false; Remember(target); if (File.Exists(SettingsStore.RecoveryPath)) File.Delete(SettingsStore.RecoveryPath); status.Text = "Сохранено · " + Path.GetFileName(path); if (page == "История") Render(); }
    async Task Copy() { Commit(); if (!await CanLeave()) return; var answer = await Ask("Копирование", "Очистить оплаты в новом проекте?", "Очистить оплаты", "Сохранить оплаты", "Отмена"); if (answer == "Отмена") return; file = ProjectStore.Copy(file, answer == "Очистить оплаты"); path = null; dirty = true; page = "Общие сведения"; Render(); }
    async Task Export(string ext, bool protocol) { Commit(); if (file.Result == null) await Calculate(); var pick = await StorageProvider.SaveFilePickerAsync(new() { Title = "Экспорт документа", SuggestedFileName = $"{file.Project.Debtor} — {(protocol ? "Протокол" : "Справка")}.{ext}", DefaultExtension = ext, FileTypeChoices = [new(ext.ToUpperInvariant()) { Patterns = ["*." + ext] }] }); if (pick?.TryGetLocalPath() is { } target) { var report = Report.Create(file.Project, file.Result!, protocol); await Task.Run(() => Exporter.Export(target, report)); status.Text = "Документ сохранён: " + target; } }
    void Remember(string p) { settings = settings with { Recent = settings.Recent.Where(x => x != p).Prepend(p).Take(50).ToList() }; SettingsStore.Save(settings); _ = RefreshRecent(); }
    async Task RefreshRecent() { var query = search.Text ?? ""; var paths = settings.Recent.Where(File.Exists).ToList(); try { if (Directory.Exists(settings.ProjectDirectory)) paths.AddRange(Directory.EnumerateFiles(settings.ProjectDirectory, "*.lpp")); } catch (IOException) { } catch (UnauthorizedAccessException) { } var matches = new List<(string Path, string Label)>(); foreach (var p in paths.Distinct().Take(200)) { try { var f = await store.LoadAsync(p); string label = $"№ {f.Project.Number} — {f.Project.Debtor}\n{f.Project.CalculationDate:dd.MM.yyyy} · {File.GetLastWriteTime(p):dd.MM.yyyy}"; if (label.Contains(query, StringComparison.OrdinalIgnoreCase)) matches.Add((p, label)); } catch { } } if (query != (search.Text ?? "")) return; recent.Children.Clear(); foreach (var e in matches.Take(15)) { var b = Button(e.Label, async () => { if (await CanLeave()) await OpenPath(e.Path); }); b.FontSize = 11; b.Foreground = Brushes.White; b.Background = Brush.Parse("#234253"); b.HorizontalAlignment = HorizontalAlignment.Stretch; b.Content = new TextBlock { Text = e.Label, TextWrapping = TextWrapping.Wrap }; recent.Children.Add(b); } }
}
